// model-ci-tooling-build-ci.test.ts — differential test of scripts/build-ci.ts against
// scripts/build-ci.sh (spec 0262 requirements 1-4, 8, 20, 21, 24): the same reference
// through both entries must give the same generated bytes, stdout, stderr and status.
// Both run in scratch trees (REPO_DIR) so the tracked tree is never written. The shell
// leg needs bash and yq; it is skipped on Windows and where yq is absent.

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { after, describe, test } from "node:test";

import { REPO, WINDOWS } from "./lib/worktree-fixtures.ts";

const SH = path.join(REPO, "scripts", "build-ci.sh");
const TS = path.join(REPO, "scripts", "build-ci.ts");
const REAL_REF = fs.readFileSync(path.join(REPO, "ci", "ci-capabilities.yml"), "utf8");
const HAS_YQ = !WINDOWS && spawnSync("yq", ["--version"], { stdio: "ignore" }).status === 0;
const SKIP = HAS_YQ ? false : "SKIP: shell leg needs bash and yq (not on win32)";
const roots: string[] = [];
after(() => {
  for (const root of roots) fs.rmSync(root, { recursive: true, force: true });
});

interface Run {
  stdout: string;
  stderr: string;
  status: number | null;
  generated: string | null;
}

/** A scratch repo root holding `ci/ci-capabilities.yml` (and a committed output if given). */
function tree(reference: string, committed?: string): string {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "crewrig-bci-")));
  roots.push(root);
  fs.mkdirSync(path.join(root, "ci"));
  fs.writeFileSync(path.join(root, "ci", "ci-capabilities.yml"), reference);
  if (committed !== undefined) fs.writeFileSync(path.join(root, ".gitlab-ci.yml"), committed);
  return root;
}

/** Run one entry in a fresh tree; paths in the output are normalised to `<ROOT>`. */
function run(entry: "sh" | "ts", args: string[], reference: string, committed?: string): Run {
  const root = tree(reference, committed);
  const [cmd, argv] =
    entry === "sh"
      ? ["bash", [SH, ...args]]
      : [process.execPath, ["--disable-warning=MODULE_TYPELESS_PACKAGE_JSON", TS, ...args]];
  const r = spawnSync(cmd, argv, {
    encoding: "utf8",
    env: { ...process.env, LC_ALL: "C", REPO_DIR: root },
  });
  const norm = (s: string): string => s.replaceAll(root, "<ROOT>");
  const out = path.join(root, ".gitlab-ci.yml");
  return {
    stdout: norm(r.stdout),
    stderr: norm(r.stderr),
    status: r.status,
    generated: fs.existsSync(out) ? fs.readFileSync(out, "utf8") : null,
  };
}

function same(args: string[], reference: string, committed?: string): void {
  const sh = run("sh", args, reference, committed);
  const ts = run("ts", args, reference, committed);
  assert.equal(ts.status, sh.status, `status\n${ts.stderr}`);
  assert.equal(ts.stderr, sh.stderr, "stderr");
  assert.equal(ts.stdout, sh.stdout, "stdout");
  assert.equal(ts.generated, sh.generated, "generated bytes");
}

describe("build-ci twin: generation", { skip: SKIP }, () => {
  test("the real reference generates the same bytes", () => same([], REAL_REF));
  test("the generated file equals the committed .gitlab-ci.yml", () => {
    const ts = run("ts", [], REAL_REF);
    assert.equal(ts.generated, fs.readFileSync(path.join(REPO, ".gitlab-ci.yml"), "utf8"));
  });
  test("unknown arguments are ignored", () => same(["--bogus", "x"], REAL_REF));
  test("--check on the committed file passes identically", () =>
    same(["--check"], REAL_REF, fs.readFileSync(path.join(REPO, ".gitlab-ci.yml"), "utf8")));
  test("--check with no committed file reports drift identically", () =>
    same(["--check"], REAL_REF));
  test("a missing reference exits 2 identically", () => {
    for (const entry of ["sh", "ts"] as const) {
      const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "crewrig-bci-")));
      roots.push(root);
      const [cmd, argv] =
        entry === "sh"
          ? ["bash", [SH]]
          : [process.execPath, ["--disable-warning=MODULE_TYPELESS_PACKAGE_JSON", TS]];
      const r = spawnSync(cmd, argv, { encoding: "utf8", env: { ...process.env, REPO_DIR: root } });
      assert.equal(r.status, 2);
      assert.equal(
        r.stderr.replaceAll(root, "<ROOT>"),
        `Error: CI reference not found: <ROOT>/ci/ci-capabilities.yml\n`,
      );
    }
  });
});

describe("build-ci twin: mutated references", { skip: SKIP }, () => {
  const mutate = (from: string, to: string): string => {
    assert.ok(REAL_REF.includes(from), `fixture anchor missing: ${from}`);
    return REAL_REF.replace(from, to);
  };
  test("an unknown runtime aborts identically", () =>
    same([], mutate("runtime: node@22", "runtime: ruby@3")));
  test("an unknown tool aborts identically", () =>
    same([], mutate("tools: [jq]", "tools: [nope]")));
  test("a drifted committed file gives the same --check diff", () => {
    const committed = fs
      .readFileSync(path.join(REPO, ".gitlab-ci.yml"), "utf8")
      .replace("image: node:22", "image: node:99");
    same(["--check"], REAL_REF, committed);
  });
  test("a changed command regenerates identically", () =>
    same([], mutate("npm run build --workspaces --if-present", 'echo "a\\b" # c')));
});
